'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var copy = require( '@stdlib/utils/copy' );
var format = require( '@stdlib/string/format' );
var parse = require( '@stdlib/utils/json-pointer/parse' );
var has = require( '@stdlib/utils/json-pointer/has' );
var setIn = require( './../../../_lib/set_in.js' );


// MAIN //

/**
* Applies a JSON Patch `replace` operation to a document immutably.
*
* ## Notes
*
* -   Implements the `replace` operation per RFC 6902 §4.3.
* -   The target location must exist (unlike `add`).
* -   If `path` is `""` (root), the entire document is replaced.
* -   The incoming `value` is deep-cloned.
* -   Returns a new document; the original is not modified (structural sharing).
*
* @param {(Object|Array)} document - source JSON document
* @param {string} path - JSON Pointer string
* @param {*} value - replacement value
* @throws {TypeError} first argument must be an object or array
* @throws {TypeError} second argument must be a string
* @throws {Error} path must reference an existing location
* @returns {(Object|Array)} new document with the value replaced
*
* @example
* var doc = { 'foo': 'bar' };
* var out = replace( doc, '/foo', 'baz' );
* // returns { 'foo': 'baz' }
*
* @example
* var doc = { 'foo': [ 1, 2, 3 ] };
* var out = replace( doc, '/foo/1', 99 );
* // returns { 'foo': [ 1, 99, 3 ] }
*/
function replace( document, path, value ) {
	var cloned;
	var tokens;

	if ( !isPlainObject( document ) && !isArray( document ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an object or an array. Value: `%s`.', document ) );
	}
	if ( !isString( path ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a string. Value: `%s`.', path ) );
	}

	tokens = parse( path );
	cloned = copy( value );

	// Root replacement:
	if ( tokens.length === 0 ) {
		return cloned;
	}

	// Verify the target exists (replace requires prior existence, unlike add):
	if ( !has( document, path ) ) {
		throw new Error( format( 'invalid operation. Target location does not exist: `%s`.', path ) );
	}

	// Perform immutable replacement:
	return setIn( document, tokens, cloned );
}


// EXPORTS //

module.exports = replace;
